@RunWith(MockitoJUnitRunner.class)
public class CommandLineRunner_createCompiler_TriageGen0Test {

    /**
     * Since createCompiler is protected, we need a subclass or a spy to access it.
     * We use a TestableCommandLineRunner to expose the protected method for testing.
     */
    private static class TestableCommandLineRunner extends CommandLineRunner {
        protected TestableCommandLineRunner(String[] args) {
            super(args);
        }

        protected TestableCommandLineRunner(String[] args, PrintStream out, PrintStream err) {
            super(args, out, err);
        }

        @Override
        public Compiler accessCreateCompiler() {
            return createCompiler();
        }
    }

    @Test
    public void testCreateCompiler_ReturnsNonNullCompiler() {
        // Arrange
        String[] args = {};
        TestableCommandLineRunner runner = new TestableCommandLineRunner(args);

        // Act
        Compiler compiler = runner.accessCreateCompiler();

        // Assert
        assertNotNull("The created compiler should not be null", compiler);
    }

    @Test
    public void testCreateCompiler_WithCustomPrintStreams() {
        // Arrange
        String[] args = {};
        PrintStream mockOut = spy(new PrintStream(System.out) {
            @Override
            public void print(String x) { super.print(x); }
        });
        PrintStream mockErr = spy(new PrintStream(System.err) {
            @Override
            public void print(String x) { super.print(x); }
        });

        TestableCommandLineRunner runner = new TestableCommandLineRunner(args, mockOut, mockErr);

        // Act
        Compiler compiler = runner.accessCreateCompiler();

        // Assert
        assertNotNull("The created compiler should not be null even with custom streams", compiler);
    }

    @Test
    public void testCreateCompiler_IsNewInstanceEveryTime() {
        // Arrange
        String[] args = {};
        TestableCommandLineRunner runner = new TestableCommandLineRunner(args);

        // Act
        Compiler compiler1 = runner.accessCreateCompiler();
        Compiler compiler2 = runner.accessCreateCompiler();

        // Assert
        assertNotNull(compiler1);
        assertNotNull(compiler2);
        assertTrue("Each call to createCompiler should return a new instance", compiler1 != compiler2);
    }
}
